package com.primehr.evidence.application;

import com.primehr.evidence.api.EvidenceFrameworkDtos.*;
import com.primehr.evidence.domain.*;
import com.primehr.evidence.infrastructure.*;
import com.primehr.shared.audit.PrimeHrAuditService;
import com.primehr.shared.exception.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service @Transactional
public class EvidenceFrameworkServiceImpl implements EvidenceFrameworkService {
    private final EvidenceFrameworkRepository roots; private final EvidenceFrameworkVersionRepository versions;
    private final EvidencePillarRepository pillars; private final EvidenceGovernanceLevelRepository levels;
    private final EvidenceIndicatorRepository indicators; private final EvidenceRequirementRepository requirements;
    private final PrimeHrAuditService audit;
    public EvidenceFrameworkServiceImpl(EvidenceFrameworkRepository roots,EvidenceFrameworkVersionRepository versions,EvidencePillarRepository pillars,EvidenceGovernanceLevelRepository levels,EvidenceIndicatorRepository indicators,EvidenceRequirementRepository requirements,PrimeHrAuditService audit){this.roots=roots;this.versions=versions;this.pillars=pillars;this.levels=levels;this.indicators=indicators;this.requirements=requirements;this.audit=audit;}

    @Override @Transactional(readOnly=true) public List<FrameworkResponse>list(String agency){return versions.findByAgencyIdOrderByCreatedAtDesc(agency).stream().map(v->response(agency,v)).toList();}
    @Override @Transactional(readOnly=true) public FrameworkResponse get(String agency,String id){return response(agency,version(agency,id));}
    @Override @Transactional(readOnly=true) public FrameworkResponse effective(String agency,LocalDate on){if(on==null)throw new IllegalArgumentException("on is required");return versions.findByAgencyIdAndStatus(agency,EvidenceDefinitionStatus.PUBLISHED).stream().filter(v->v.effectiveOn(on)).findFirst().map(v->response(agency,v)).orElseThrow(()->new ResourceNotFoundException("No evidence framework is effective on the requested date"));}
    @Override public FrameworkResponse create(String agency,FrameworkInput in,String correlation){if(in.recordVersion()!=null)throw new IllegalArgumentException("recordVersion must be omitted for new records");String normalized=norm(in.code());if(roots.existsByAgencyIdAndNormalizedCode(agency,normalized))throw new OptimisticConflictException("Evidence framework code already exists");var root=roots.saveAndFlush(new EvidenceFramework(agency,in.code()));var value=versions.saveAndFlush(new EvidenceFrameworkVersion(agency,root.getId(),1,null,in.title(),in.description(),in.issuingBody(),in.legalBasis(),in.authorityReference(),in.internalUseDisclaimer()));var out=response(agency,value);record(agency,"CREATE_EVIDENCE_FRAMEWORK_DRAFT",value,null,out,null,correlation);return out;}
    @Override public FrameworkResponse update(String agency,String id,FrameworkInput in,String correlation){var value=version(agency,id);check(value.getVersion(),in.recordVersion());var root=root(agency,value.getFrameworkId());if(!norm(root.getCode()).equals(norm(in.code())))throw new IllegalArgumentException("Framework code cannot change");var before=response(agency,value);value.update(in.title(),in.description(),in.issuingBody(),in.legalBasis(),in.authorityReference(),in.internalUseDisclaimer());value=versions.saveAndFlush(value);var out=response(agency,value);record(agency,"UPDATE_EVIDENCE_FRAMEWORK_DRAFT",value,before,out,null,correlation);return out;}
    @Override public FrameworkResponse replaceContent(String agency,String id,ContentInput in,String correlation){var value=version(agency,id);check(value.getVersion(),in.recordVersion());validate(in);var before=response(agency,value);replace(agency,value,in);value.contentChanged();value=versions.saveAndFlush(value);var out=response(agency,value);record(agency,"REPLACE_EVIDENCE_FRAMEWORK_CONTENT",value,before,out,null,correlation);return out;}
    @Override public FrameworkResponse revise(String agency,String id,Transition in,String correlation){var prior=version(agency,id);check(prior.getVersion(),in.recordVersion());if(prior.getStatus()!=EvidenceDefinitionStatus.PUBLISHED)throw new IllegalLifecycleTransitionException("Only a published framework may be revised");int next=versions.findByAgencyIdAndFrameworkIdOrderByDefinitionVersionDesc(agency,prior.getFrameworkId()).stream().mapToInt(EvidenceFrameworkVersion::getDefinitionVersion).max().orElse(0)+1;var value=versions.saveAndFlush(new EvidenceFrameworkVersion(agency,prior.getFrameworkId(),next,prior.getId(),prior.getTitle(),prior.getDescription(),prior.getIssuingBody(),prior.getLegalBasis(),prior.getAuthorityReference(),prior.getInternalUseDisclaimer()));copyContent(agency,prior.getId(),value);value.contentChanged();value=versions.saveAndFlush(value);var out=response(agency,value);record(agency,"REVISE_EVIDENCE_FRAMEWORK",value,null,out,in.reason(),correlation);return out;}
    @Override public FrameworkResponse publish(String agency,String id,Publish in,String correlation){var value=version(agency,id);check(value.getVersion(),in.recordVersion());ensureComplete(agency,id);if(in.effectiveTo()!=null&&in.effectiveTo().isBefore(in.effectiveFrom()))throw new IllegalArgumentException("effectiveTo cannot precede effectiveFrom");var published=versions.findByAgencyIdAndStatus(agency,EvidenceDefinitionStatus.PUBLISHED);for(var other:published){if(other.getId().equals(id))continue;if(value.getSupersedesId()!=null&&other.getId().equals(value.getSupersedesId()))continue;if(overlaps(in.effectiveFrom(),in.effectiveTo(),other.getEffectiveFrom(),other.getEffectiveTo()))throw new OptimisticConflictException("Another evidence framework is effective during the requested period");}var before=response(agency,value);Instant now=Instant.now();if(value.getSupersedesId()!=null){var prior=version(agency,value.getSupersedesId());if(!prior.getFrameworkId().equals(value.getFrameworkId()))throw new IllegalArgumentException("Successor framework lineage is invalid");prior.supersede(in.effectiveFrom(),audit.currentActor(),now);versions.saveAndFlush(prior);}value.publish(in.effectiveFrom(),in.effectiveTo(),audit.currentActor(),now);value=versions.saveAndFlush(value);var out=response(agency,value);record(agency,"PUBLISH_EVIDENCE_FRAMEWORK",value,before,out,in.reason(),correlation);return out;}
    @Override public FrameworkResponse retire(String agency,String id,Transition in,String correlation){var value=version(agency,id);check(value.getVersion(),in.recordVersion());var before=response(agency,value);value.retire(audit.currentActor(),in.reason(),Instant.now());value=versions.saveAndFlush(value);var out=response(agency,value);record(agency,"RETIRE_EVIDENCE_FRAMEWORK",value,before,out,in.reason(),correlation);return out;}

    private void replace(String agency,EvidenceFrameworkVersion value,ContentInput in){requirements.deleteByAgencyIdAndFrameworkVersionId(agency,value.getId());requirements.flush();indicators.deleteByAgencyIdAndFrameworkVersionId(agency,value.getId());indicators.flush();levels.deleteByAgencyIdAndFrameworkVersionId(agency,value.getId());levels.flush();pillars.deleteByAgencyIdAndFrameworkVersionId(agency,value.getId());pillars.flush();var savedPillars=pillars.saveAllAndFlush(in.pillars().stream().map(x->new EvidencePillar(agency,value.getId(),x.code(),x.title(),x.description(),x.displayOrder())).toList());Map<String,EvidencePillar>pillarMap=savedPillars.stream().collect(Collectors.toMap(x->norm(x.getCode()),Function.identity()));levels.saveAllAndFlush(in.levels().stream().map(x->new EvidenceGovernanceLevel(agency,value.getId(),x.code(),x.label(),x.description(),x.displayOrder())).toList());var savedIndicators=indicators.saveAllAndFlush(in.indicators().stream().map(x->new EvidenceIndicator(agency,value.getId(),pillarMap.get(norm(x.pillarCode())).getId(),x.code(),x.title(),x.description(),x.evaluationGuidance(),x.displayOrder())).toList());Map<String,EvidenceIndicator>indicatorMap=savedIndicators.stream().collect(Collectors.toMap(x->norm(x.getCode()),Function.identity()));requirements.saveAllAndFlush(in.requirements().stream().map(x->new EvidenceRequirement(agency,value.getId(),indicatorMap.get(norm(x.indicatorCode())).getId(),x.code(),x.title(),x.evidenceGuidance(),x.evidenceType(),x.recurrenceMonths(),x.freshnessDays(),x.required(),x.allowsNotApplicable(),x.displayOrder())).toList());}
    private void copyContent(String agency,String priorId,EvidenceFrameworkVersion target){var oldP=pillars.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(agency,priorId);var newP=pillars.saveAllAndFlush(oldP.stream().map(x->new EvidencePillar(agency,target.getId(),x.getCode(),x.getTitle(),x.getDescription(),x.getDisplayOrder())).toList());Map<String,EvidencePillar>pByOld=new HashMap<>();for(int i=0;i<oldP.size();i++)pByOld.put(oldP.get(i).getId(),newP.get(i));levels.saveAllAndFlush(levels.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(agency,priorId).stream().map(x->new EvidenceGovernanceLevel(agency,target.getId(),x.getCode(),x.getLabel(),x.getDescription(),x.getDisplayOrder())).toList());var oldI=indicators.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(agency,priorId);var newI=indicators.saveAllAndFlush(oldI.stream().map(x->new EvidenceIndicator(agency,target.getId(),pByOld.get(x.getPillarId()).getId(),x.getCode(),x.getTitle(),x.getDescription(),x.getEvaluationGuidance(),x.getDisplayOrder())).toList());Map<String,EvidenceIndicator>iByOld=new HashMap<>();for(int i=0;i<oldI.size();i++)iByOld.put(oldI.get(i).getId(),newI.get(i));requirements.saveAllAndFlush(requirements.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(agency,priorId).stream().map(x->new EvidenceRequirement(agency,target.getId(),iByOld.get(x.getIndicatorId()).getId(),x.getCode(),x.getTitle(),x.getEvidenceGuidance(),x.getEvidenceType(),x.getRecurrenceMonths(),x.getFreshnessDays(),x.isRequired(),x.isAllowsNotApplicable(),x.getDisplayOrder())).toList());}
    private void validate(ContentInput in){unique(in.pillars().stream().map(PillarInput::code).toList(),"pillar code");unique(in.pillars().stream().map(x->x.displayOrder()+"").toList(),"pillar display order");unique(in.levels().stream().map(LevelInput::code).toList(),"governance level code");unique(in.levels().stream().map(x->x.displayOrder()+"").toList(),"governance level display order");unique(in.indicators().stream().map(IndicatorInput::code).toList(),"indicator code");unique(in.requirements().stream().map(RequirementInput::code).toList(),"requirement code");Set<String>p=in.pillars().stream().map(x->norm(x.code())).collect(Collectors.toSet());for(var x:in.indicators())if(!p.contains(norm(x.pillarCode())))throw new IllegalArgumentException("Indicator references an unknown pillar: "+x.pillarCode());Set<String>i=in.indicators().stream().map(x->norm(x.code())).collect(Collectors.toSet());for(var x:in.requirements())if(!i.contains(norm(x.indicatorCode())))throw new IllegalArgumentException("Requirement references an unknown indicator: "+x.indicatorCode());groupOrder(in.indicators().stream().map(x->norm(x.pillarCode())+":"+x.displayOrder()).toList(),"indicator display order");groupOrder(in.requirements().stream().map(x->norm(x.indicatorCode())+":"+x.displayOrder()).toList(),"requirement display order");}
    private void ensureComplete(String agency,String id){if(pillars.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(agency,id).isEmpty()||levels.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(agency,id).isEmpty()||indicators.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(agency,id).isEmpty()||requirements.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(agency,id).isEmpty())throw new IllegalLifecycleTransitionException("A framework requires pillars, reference-only governance labels, indicators, and requirements before publication");}
    private FrameworkResponse response(String agency,EvidenceFrameworkVersion v){var root=root(agency,v.getFrameworkId());var ps=pillars.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(agency,v.getId());Map<String,String>pCode=ps.stream().collect(Collectors.toMap(EvidencePillar::getId,EvidencePillar::getCode));var is=indicators.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(agency,v.getId());Map<String,String>iCode=is.stream().collect(Collectors.toMap(EvidenceIndicator::getId,EvidenceIndicator::getCode));return new FrameworkResponse(v.getId(),v.getFrameworkId(),root.getCode(),v.getTitle(),v.getDescription(),v.getIssuingBody(),v.getLegalBasis(),v.getAuthorityReference(),v.getInternalUseDisclaimer(),v.getContentRevision(),v.getDefinitionVersion(),v.getSupersedesId(),v.getStatus().name(),v.getEffectiveFrom(),v.getEffectiveTo(),v.getVersion(),ps.stream().map(x->new PillarResponse(x.getId(),x.getCode(),x.getTitle(),x.getDescription(),x.getDisplayOrder())).toList(),levels.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(agency,v.getId()).stream().map(x->new LevelResponse(x.getId(),x.getCode(),x.getLabel(),x.getDescription(),x.isReferenceOnly(),x.getDisplayOrder())).toList(),is.stream().map(x->new IndicatorResponse(x.getId(),pCode.get(x.getPillarId()),x.getCode(),x.getTitle(),x.getDescription(),x.getEvaluationGuidance(),x.getDisplayOrder())).toList(),requirements.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(agency,v.getId()).stream().map(x->new RequirementResponse(x.getId(),iCode.get(x.getIndicatorId()),x.getCode(),x.getTitle(),x.getEvidenceGuidance(),x.getEvidenceType().name(),x.getRecurrenceMonths(),x.getFreshnessDays(),x.isRequired(),x.isAllowsNotApplicable(),x.getDisplayOrder())).toList());}
    private EvidenceFrameworkVersion version(String agency,String id){return versions.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Evidence framework version not found"));}private EvidenceFramework root(String agency,String id){return roots.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Evidence framework not found"));}
    private void record(String agency,String action,EvidenceFrameworkVersion value,Object before,Object after,String reason,String correlation){audit.record(agency,action,"EVIDENCE_FRAMEWORK_VERSION",value.getId(),value.getDefinitionVersion(),value.getVersion(),before,after,reason,correlation);}
    private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Record version is stale");}private static String norm(String x){return x==null?"":x.trim().toUpperCase(Locale.ROOT);}private static void unique(List<String>values,String label){Set<String>s=new HashSet<>();for(String v:values)if(!s.add(norm(v)))throw new IllegalArgumentException("Duplicate "+label+": "+v);}private static void groupOrder(List<String>values,String label){Set<String>s=new HashSet<>();for(String v:values)if(!s.add(v))throw new IllegalArgumentException("Duplicate "+label+": "+v);}private static boolean overlaps(LocalDate a1,LocalDate a2,LocalDate b1,LocalDate b2){return (a2==null||!a2.isBefore(b1))&&(b2==null||!b2.isBefore(a1));}
}
